  "type": "object",
  "required": ["id", "purpose", "scope", "non_goals", "acceptance_criteria"],
  "additionalProperties": false,
  "properties": {
    "id": {
      "type": "string",
      "description": "Unique identifier (e.g. SPEC-001)"
    },
    "purpose": {
      "type": "string",
      "description": "One paragraph: what this spec defines and why it exists"
    },
    "scope": {
      "type": "string",
      "description": "What is covered by this spec"
    },
    "non_goals": {
      "type": "array",
      "minItems": 1,
      "items": { "type": "string" },
      "description": "Explicitly excluded from this spec"
    },
    "api_surface": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["name", "signature", "description"],
        "additionalProperties": false,
        "properties": {
          "name": { "type": "string" },
          "signature": { "type": "string" },
          "description": { "type": "string" },
          "error_conditions": { "type": "array", "items": { "type": "string" } }
        }
      }
    },
    "acceptance_criteria": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["id", "criterion"],
        "additionalProperties": false,
        "properties": {
          "id": { "type": "string" },
          "criterion": {
            "type": "string",
            "description": "A testable proposition — something that can be confirmed true or false"
          },
